import{z as p,x as s,o as t,c as B,q as m,j as n,D as i,d as r,s as E,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SimPO 原文","description":"","frontmatter":{"title":"SimPO 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/simpo-paper.md","filePath":"llm/simpo-paper.md","lastUpdated":1791413859000}'),d={name:"llm/simpo-paper.md"};function A(h,a,P,g,D,c){const l=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=m('<h1 id="simpo-原文" tabindex="-1">SimPO 原文 <a class="header-anchor" href="#simpo-原文" aria-label="Permalink to &quot;SimPO 原文&quot;">​</a></h1><div class="epigraph"><p>隐含奖励直接取当前策略的长度平均对数概率，logistic 里再减一段目标间隔，参考模型可以从训练图里拿掉。</p><footer>—— Meng, Xia, Chen，SimPO: Simple Preference Optimization with a Reference-Free Reward，2024</footer></div><p>已有 <a href="/llm/simpo">SimPO</a> 篇写平均对数概率作为奖励意味着什么、\\(\\gamma\\) 与学习率的几何差别、无 SFT 项时的退化。本篇钉 Meng、Xia、Chen 原文（arXiv:2405.14734）：他们如何把 DPO 隐含奖励的两条后果——必须驻留参照、对数和对长度不公平——写成可消掉的设计，AlpacaEval 2 / Arena-Hard 上的对照应怎么读，以及「简单」二字覆盖了哪些未写入损失的前提。超参网格与 tokenizer 陷阱见前一篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DPO 的奖励是 \\(\\beta\\log(\\pi_\\theta/\\pi_{\\mathrm{ref}})\\)，分子分母都是序列对数和。后果立刻有两条。训练图要一份冻结 SFT，小模型微调时显存与检查点管理翻倍。未归一化的和偏爱更长的 \\(y_w\\) 或更短的 \\(y_l\\)：多一个还过得去的 token 就往和里加一项，对比可以被长度操纵。参照差能消掉一部分两侧共同的长度趋势，但消不干净，而且为这个差要付第二份前向。</p><p>无参考之后必须另找标量：对长度公平、对偏好敏感、还要让 logistic 有足够梯度。token 平均 \\(\\frac{1}{|y|}\\sum\\log\\pi\\) 与生成时的平均 NLL 同构，直觉是「每个词都比较像模型会说的」。平均差往往偏小，\\(\\sigma\\) 工作在平坦区，模型学成略偏好就停。需要显式间隔，把「差一点点」改成「差出 \\(\\gamma\\)」。问题设定是：在同一套成对数据上，这个无参考奖励能否达到或超过 DPO，而不是在另一套标注协议上另起炉灶。</p><p><span class="marginnote">数字实例：设 10-token 的 \\(y_w\\) 每词平均对数概率 \\(-0.5\\)，5-token 的 \\(y_l\\) 每词 \\(-1.0\\)。未归一化的和都是 \\(-5\\)，对比里看不出谁好；除以长度后是 \\(-0.5\\) 对 \\(-1.0\\)，「每词更像人话」的那条才显出来。长度归一化要修的就是这本账。</span></p><h3 id="参照消掉的不只是长度" tabindex="-1">参照消掉的不只是长度 <a class="header-anchor" href="#参照消掉的不只是长度" aria-label="Permalink to &quot;参照消掉的不只是长度&quot;">​</a></h3><p>\\(\\log\\pi_\\theta-\\log\\pi_{\\mathrm{ref}}\\) 还消掉参照里已经很高的套话：礼貌开头在参照里同样高，差接近 0，DPO 不会额外给奖。SimPO 没有这条差，平均对数概率会把「模型本来就会的模板」当成高奖励。间隔 \\(\\gamma\\) 只拉相对差，不恢复「相对 SFT 的绝对偏离」。原文把这写成简单性的一部分；读实验时必须意识到：AlpacaEval 偏好话多、礼貌、列表，正好可能与「高平均对数概率」同向，不一定泛化到硬拒答或罕见格式。</p><p><span class="marginnote">\\(|y|\\) 由 tokenizer 决定。中文同一句在不同词表下平均 NLL 不可比。原文实验在固定词表的 Llama / Mistral 上比算法，不比跨词表的奖励绝对值。训练与离线 Best-of-N 必须用同一套分词与同一套平均。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义</p> \\[r_\\theta(x,y)=\\frac{\\beta}{|y|}\\log\\pi_\\theta(y\\mid x), \\]<p>成对损失为</p> \\[\\mathcal{L}_{\\mathrm{SimPO}}=-\\mathbb{E}\\log\\sigma\\bigl(r_\\theta(x,y_w)-r_\\theta(x,y_l)-\\gamma\\bigr). \\]<p>没有 SFT 辅助项，没有 \\(\\pi_{\\mathrm{ref}}\\)。\\(\\beta\\) 放大平均差；\\(\\gamma\\gt 0\\) 是目标间隔，满足后 logistic 梯度变小，未满足的对继续推。数据仍是 \\((x,y_w,y_l)\\)，与 DPO 相同。作者在 UltraFeedback 一类成对集上，从同一 SFT 检查点出发比 DPO、IPO、KTO、ORPO 等，主榜是 AlpacaEval 2（含长度控制胜率）与 Arena-Hard。</p><h3 id="间隔是-margin-不是-kl-系数" tabindex="-1">间隔是 margin 不是 KL 系数 <a class="header-anchor" href="#间隔是-margin-不是-kl-系数" aria-label="Permalink to &quot;间隔是 margin 不是 KL 系数&quot;">​</a></h3><p>DPO 的 \\(\\beta\\) 来自 KL 约束的温度，出现在对数比前面。SimPO 的 \\(\\beta\\) 只缩放平均 NLL，量纲不同，网格不能互抄。\\(\\gamma\\) 移动决策面：已经隔开的样本几乎不再更新，卡在间隔附近的难对承担主要梯度，与 <a href="/llm/slic">SLiC</a> 铰链的 \\(\\delta\\) 近亲，差别是平滑的 \\(\\log\\sigma\\) 而不是 \\(\\max(0,\\cdot)\\)。原文消融显示两项都需要：只平均不加 \\(\\gamma\\)，分离不够；只加间隔不平均，长度偏置回来。具体数值以论文表为准，迁移时重新扫。</p>',18)),(t(),n(o,null,{default:i(()=>[E(l,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20YW%5B%22yw%20token%20%E5%AF%B9%E6%95%B0%E6%A6%82%E7%8E%87%22%5D%20--%3E%20AVG%5B%22%E9%99%A4%E4%BB%A5%E9%95%BF%E5%BA%A6%EF%BC%8C%E4%B9%98%20%CE%B2%22%5D%0A%20%20YL%5B%22yl%20token%20%E5%AF%B9%E6%95%B0%E6%A6%82%E7%8E%87%22%5D%20--%3E%20AVG2%5B%22%E9%99%A4%E4%BB%A5%E9%95%BF%E5%BA%A6%EF%BC%8C%E4%B9%98%20%CE%B2%22%5D%0A%20%20AVG%20--%3E%20M%5B%22%E5%B7%AE%E5%87%8F%E5%8E%BB%20%CE%B3%22%5D%0A%20%20AVG2%20--%3E%20M%0A%20%20M%20--%3E%20L%5B%22-log%20%CF%83%22%5D%0A%20%20REF%5B%22%E6%97%A0%E5%8F%82%E8%80%83%E6%A8%A1%E5%9E%8B%22%5D%20-.-%3E%20L%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"主结果该怎么读",tabindex:"-1"},[r("主结果该怎么读 "),e("a",{class:"header-anchor",href:"#主结果该怎么读","aria-label":'Permalink to "主结果该怎么读"'},"​")],-1)),a[4]||(a[4]=e("p",null,"叙事是：在 Llama-3、Mistral 等指令或基座 + UltraFeedback 设定下，SimPO 的长度控制 AlpacaEval 与 Arena-Hard 超过同数据 DPO，且少一份模型。长度控制胜率是关键列——未控制的原始胜率会被话多抬高，而 SimPO 的训练目标本身就在打长度归一。即便如此，GPT 裁判仍偏好列表与解释，间隔过大时模型仍可能变长；原文把生成长度当作要报告的量，落地篇把它升为一等监控。不要把某一检查点的 40%+ LC 胜率写成算法常数，裁判、提示集、解码参数全变。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"用平均 NLL 当奖励，等于把「自己觉得顺」对齐到「人觉得好」。当 \\(y_w\\) 确实更流畅、更像 SFT 风格时很有效；当更好的回答是更短、更硬、平均 NLL 反而更差的拒答或工具调用时，符号会错。DPO 的参照差在这里更有用：罕见但相对参照提高的模式仍可获正隐含奖励。这是无参考简单性的机制代价，不是漏做 SFT。",-1)),(t(),n(o,null,{default:i(()=>[E(l,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20DP%5B%22DPO%EF%BC%9A%E9%A9%BB%E7%95%99%E5%8F%82%E8%80%83%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20%20%20A%5B%22%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E5%AF%B9%E6%95%B0%E5%92%8C%22%5D%20--%3E%20C%5B%22%E5%87%8F%E5%8F%82%E8%80%83%E6%A8%A1%E5%9E%8B%E5%AF%B9%E6%95%B0%E5%92%8C%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%CE%B2%20%E4%B9%98%E5%AF%B9%E6%95%B0%E6%AF%94%22%5D%0A%20%20end%0A%20%20subgraph%20SP%5B%22SimPO%EF%BC%9A%E6%97%A0%E5%8F%82%E8%80%83%22%5D%0A%20%20%20%20B%5B%22%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E5%AF%B9%E6%95%B0%E5%92%8C%22%5D%20--%3E%20E%5B%22%E9%99%A4%E4%BB%A5%20token%20%E6%95%B0%E5%8F%96%E5%B9%B3%E5%9D%87%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%CE%B2%20%E4%B9%98%E5%B9%B3%E5%9D%87%E5%86%8D%E5%87%8F%20%CE%B3%22%5D%0A%20%20end%0A%20%20D%20--%3E%20G%5B%22%E8%BF%9B%20logistic%20%E6%88%90%E5%AF%B9%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=m('<p>无 NLL 锚时，理论上可把 \\(y_w\\) 与 \\(y_l\\) 的平均对数概率一起降低、只要差保持 \\(\\gamma\\)。原文实验从已 SFT 的模型短训，把这种退化压住。「简单」描述的是训练图，不是从随机初始化一步到位。从基座直训应先 SFT，这一点与 ORPO 原文的单体叙事不同，两篇不要混成「无参考都可以冷启动」。</p><p><span class="marginnote">直觉类比：用平均对数概率当奖励，是让模型「给自己觉得顺口的答案打高分」。多数聊天回答它确实觉得顺，于是奏效；可更好的答案若是一句生硬的「我不知道」，模型自己都嫌不顺口，奖励符号就反了。参照差相当于「比自己平时的口语好就行」，换了个基准。</span></p><p><span class="marginnote">SimPO 不输出可当 RM 用的绝对分数。\\(r_\\theta\\) 依赖当前 \\(\\pi_\\theta\\)，不能拿去离线给别的模型做 Best-of-N，除非那个模型就是正在训的 \\(\\pi\\)。需要独立打分器，仍要训 RM。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>省参考前向，代码路径比 DPO 短，比 ORPO 还少一项 SFT 损失。代价：套话校准弱、高分低似然的好回答不友好、\\(\\beta\\) 与 \\(\\gamma\\) 耦合、与 tokenizer 绑定。离线若用未归一化对数和去挑 winner，会和训练目标打架。KTO 的不成对标签、ORPO 的单体 NLL、DPO 的 KL 语义，这篇都不提供。</p><p>作者单位含普林斯顿 NLP。后续大量开源「SimPO 配方」换数据、换裁判，数字不能回写进 2024 年这篇的抽象。安全对齐、多目标冲突仍在标注层，不在平均 NLL 里。</p><p><span class="marginnote">出处钉 Yu Meng、Mengzhou Xia、Danqi Chen，arXiv:2405.14734。标题 Simple 容易被读成「没有超参」。实际上 \\(\\beta\\)、\\(\\gamma\\)、是否从 SFT 出发、epoch，每一项都比算法名更能决定结果。</span></p><h3 id="何时不必上原文" tabindex="-1">何时不必上原文 <a class="header-anchor" href="#何时不必上原文" aria-label="Permalink to &quot;何时不必上原文&quot;">​</a></h3><p>调平均对数概率与间隔、监控长度，读 <a href="/llm/simpo">SimPO</a>。需要引用 Arena-Hard / AlpacaEval 2 表内对照、需要向别人解释「无参考奖励」的定义来自这篇而不是民间删掉 \\(\\pi_{\\mathrm{ref}}\\) 的 DPO，再读原文。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SimPO 原文定义无参考奖励为长度平均对数概率，BT 损失中减目标间隔 \\(\\gamma\\)。</li><li>针对 DPO 的参照显存与对数和长度偏置；放弃的是参照校准。</li><li>主榜是长度控制的指令跟随评测，数字随裁判变，须看原文表。</li><li>宜从 SFT 短训；无 SFT 项时存在双边一起塌的退化模式。</li><li>\\(\\beta\\) 不是 KL 系数；\\(\\gamma\\) 是 margin。</li><li>出处：Meng, Xia, Chen，<em>SimPO: Simple Preference Optimization with a Reference-Free Reward</em>，2024；落地对照见 <a href="/llm/simpo">SimPO</a>。</li></ul>',11))])}const _=p(d,[["render",A]]);export{S as __pageData,_ as default};
